// END precache
const KNOWN = new Set(PRECACHE.map((p) => new URL(p, self.location.href).href));
const APP_SHELL = new URL('app/', self.location.href).href;

self.addEventListener('install', (event) => {
  // addAll is atomic: one failed file fails the install, so the previous worker and cache stay in force.
  event.waitUntil(caches.open(CACHE)
    .then((c) => c.addAll(PRECACHE.map((p) => new Request(new URL(p, self.location.href), { cache: 'reload' }))))
    .then(() => self.skipWaiting()));
});

self.addEventListener('activate', (event) => {
  event.waitUntil(caches.keys()
    .then((ks) => Promise.all(ks.filter((k) => k.startsWith('sqc-') && k !== CACHE).map((k) => caches.delete(k))))
    .then(() => self.clients.claim()));
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  event.respondWith(respond(req, url.origin + url.pathname));
});

const SLOW = Symbol('slow');
const SLOW_MS = 3000;  // after this, a cached copy is served instead of waiting (issue 169)

// Network-first. The download is never aborted (a slow body still completes); if the network has not answered in
// SLOW_MS and a cached copy exists, that copy is served instead. A failed network falls back to the cache.
async function respond(req, bare) {
  const net = fetch(req, { cache: 'no-cache' }).then((res) => {
    // Refresh only files the app fetches (bounded cache); a 404 is returned as is (Eval "missing" relies on it).
    if (res.ok && KNOWN.has(bare)) {
      const copy = res.clone();  // before the page reads the body
      caches.open(CACHE).then((c) => c.put(bare, copy)).catch(() => {});
    }
    return res;
  });
  net.catch(() => {});  // observed below; avoids an unhandled rejection when the cached copy wins
  const cached = () => caches.match(req, { ignoreSearch: true });
  try {
    const first = await Promise.race([net, new Promise((r) => setTimeout(r, SLOW_MS, SLOW))]);
    if (first !== SLOW) return first;
    return (await cached()) ?? await net;
  } catch (err) {
    const hit = await cached();
    if (hit) return hit;
    // Only app/ pages get the shell; another page (e.g. docs/EVAL.md) would break with app-relative CSS/JS.
    if (req.mode === 'navigate' && bare.startsWith(APP_SHELL)) {
      const shell = await caches.match(APP_SHELL);
      if (shell) return shell;
    }
    throw err;
  }
}
